import java.util.*;class Solution{public List<String> fullJustify(String[]w,int W){List<String>o=new ArrayList<>();for(int i=0;i<w.length;){int j=i,len=0;while(j<w.length&&len+w[j].length()+j-i<=W)len+=w[j++].length();int gaps=j-i-1;StringBuilder l=new StringBuilder();if(j==w.length||gaps==0){for(int k=i;k<j;k++){if(k>i)l.append(' ');l.append(w[k]);}while(l.length()<W)l.append(' ');}else{int s=W-len,b=s/gaps,e=s%gaps;for(int k=i;k<j;k++){l.append(w[k]);if(k<j-1)l.append(" ".repeat(b+(k-i<e?1:0)));}}o.add(l.toString());i=j;}return o;}}
